package fr.darkvodou.facets.symmetry;

import javax.annotation.Nullable;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * The symmetries of //sym set, each made of the transforms generated by a few mirrors.
 */
public enum SymmetryType {

    /** Point symmetry in the horizontal plane: a half turn around the vertical axis (2 blocks) */
    SIMPLE2D("simple2d", Transform.HALF_TURN_Y),
    /** Mirror through the plane perpendicular to x (2 blocks) */
    PLANX("planx", Transform.MIRROR_X),
    PLANY("plany", Transform.MIRROR_Y),
    PLANZ("planz", Transform.MIRROR_Z),
    /** PLANX and PLANZ together (4 blocks) */
    CROSS2D("cross2d", Transform.MIRROR_X, Transform.MIRROR_Z),
    /** PLANX, PLANY and PLANZ together (8 blocks) */
    CROSS3D("cross3d", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z),
    /** CROSS2D with the 45° diagonals (8 blocks) */
    STAR2D("star2d", Transform.MIRROR_X, Transform.MIRROR_Z, Transform.SWAP_XZ),
    /** STAR2D mirrored up and down (16 blocks) */
    STAR3D("star3d", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z, Transform.SWAP_XZ),
    /** STAR3D around each of the three axes: every rotation and mirror of the cube (48 blocks) */
    MEGASTAR("megastar", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z, Transform.SWAP_XZ,
            Transform.SWAP_XY);

    private final String id;
    // Without the identity
    private final List<Transform> transforms;

    SymmetryType(String id, Transform... generators) {
        this.id = id;
        this.transforms = generate(generators);
    }

    public String id() {
        return id;
    }

    /**
     * @return the transforms giving the copies of a block, without the identity
     */
    public List<Transform> transforms() {
        return transforms;
    }

    /**
     * @return the number of blocks placed for one, counting it
     */
    public int copies() {
        return transforms.size() + 1;
    }

    @Nullable
    public static SymmetryType fromId(String id) {
        String lower = id.toLowerCase(Locale.ROOT);
        for (SymmetryType type : values()) {
            if (type.id.equals(lower)) {
                return type;
            }
        }
        return null;
    }

    /**
     * @return every combination of the generators, without the identity
     */
    private static List<Transform> generate(Transform... generators) {
        Set<Transform> group = new LinkedHashSet<>();
        Deque<Transform> pending = new ArrayDeque<>();
        group.add(Transform.IDENTITY);
        pending.add(Transform.IDENTITY);
        while (!pending.isEmpty()) {
            Transform current = pending.poll();
            for (Transform generator : generators) {
                Transform next = generator.after(current);
                if (group.add(next)) {
                    pending.add(next);
                }
            }
        }
        List<Transform> result = new ArrayList<>(group);
        result.remove(Transform.IDENTITY);
        return List.copyOf(result);
    }
}
